-- 0021 Book identifiers: permanent platform-assigned Book IDs, and an immutable
-- copy of that ID on every order line at the moment of purchase.
--
-- A Book ID looks like INK-BK-000001. It is not an ISBN and not an order
-- number: it identifies a catalogue record inside this marketplace.
--
-- Guarantees:
--   * generated by the database from a sequence, so no two books can collide;
--   * never recycled — nextval() is monotonic and a rolled-back insert does not
--     return its number to the pool;
--   * assigned only by a BEFORE INSERT trigger, so an author cannot supply one;
--   * frozen by a BEFORE UPDATE trigger, so editing a title or price cannot
--     change it, and nothing (not even the service role) can rewrite it;
--   * copied onto order_items at insert time and frozen there too, so
--     historical sales, refunds, reports and accounting keep the identifier
--     even after the book is edited, archived or soft-deleted.
--
-- The existing `book_id` foreign key on order_items is deliberately kept: the
-- live relationship and the historical snapshot serve different purposes.

create sequence public.book_code_seq as bigint start 1;

create or replace function private.assign_book_code() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.book_code is not null then
    raise exception 'book_code is assigned by the platform' using errcode = '42501';
  end if;
  new.book_code := 'INK-BK-' || lpad(nextval('public.book_code_seq')::text, 6, '0');
  return new;
end; $$;

alter table public.books add column book_code text;

-- Backfill oldest-first so existing catalogue rows get stable, ordered IDs.
-- This must run before the immutability trigger exists, or it blocks itself.
with ordered as (
  select id, row_number() over (order by created_at, id) as rn
  from public.books
  where book_code is null
)
update public.books b
   set book_code = 'INK-BK-' || lpad(o.rn::text, 6, '0')
  from ordered o
 where o.id = b.id;

-- Continue the sequence after the highest backfilled number.
select setval(
  'public.book_code_seq',
  coalesce((select max(substring(book_code from 8)::bigint) from public.books), 0) + 1,
  false
);

alter table public.books
  add constraint books_book_code_key unique (book_code),
  alter column book_code set not null;

create trigger books_assign_code
  before insert on public.books
  for each row execute function private.assign_book_code();

create or replace function private.guard_book_code() returns trigger
language plpgsql as $$
begin
  if new.book_code is distinct from old.book_code then
    raise exception 'book_code is permanent and cannot be changed' using errcode = '42501';
  end if;
  return new;
end; $$;

create trigger books_guard_code
  before update on public.books
  for each row execute function private.guard_book_code();

create index books_book_code_idx on public.books (book_code);

-- ---------------------------------------------------------------- order snapshot
-- A denormalised copy kept on the line itself. Reports read this column rather
-- than joining books, so a later edit or archive cannot rewrite history.
alter table public.order_items add column book_code_snapshot text;

update public.order_items oi
   set book_code_snapshot = b.book_code
  from public.books b
 where b.id = oi.book_id
   and oi.book_code_snapshot is null;

alter table public.order_items alter column book_code_snapshot set not null;

create or replace function private.snapshot_book_code() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.book_code_snapshot is not null then
    raise exception 'book_code_snapshot is captured by the platform' using errcode = '42501';
  end if;
  select b.book_code into new.book_code_snapshot
    from public.books b
   where b.id = new.book_id;
  if new.book_code_snapshot is null then
    raise exception 'cannot snapshot book code: book % not found', new.book_id
      using errcode = '23502';
  end if;
  return new;
end; $$;

create trigger order_items_snapshot_code
  before insert on public.order_items
  for each row execute function private.snapshot_book_code();

create or replace function private.guard_order_item_snapshot() returns trigger
language plpgsql as $$
begin
  if new.book_code_snapshot is distinct from old.book_code_snapshot then
    raise exception 'book_code_snapshot is immutable' using errcode = '42501';
  end if;
  return new;
end; $$;

create trigger order_items_guard_snapshot
  before update on public.order_items
  for each row execute function private.guard_order_item_snapshot();

create index order_items_book_code_idx on public.order_items (book_code_snapshot);

comment on column public.books.book_code is
  'Permanent platform-assigned Book ID (INK-BK-######). Not an ISBN, not an order number. Assigned on insert, immutable thereafter.';
comment on column public.order_items.book_code_snapshot is
  'Copy of books.book_code taken when the line was created. Frozen forever for reporting, refunds and accounting.';
